INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (401, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0.0, 0.0, 10046, 102301, 24001, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アヤネ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (402, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 2.21, 0.0, 10046, 102301, 24002, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アヤネ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (403, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0.0, 0.0, 10046, 102301, 24003, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アヤネ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (701, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 1.99, 0.0, 10046, 192201, 24004, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アサヒ", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (702, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 2.21, 0.0, 10046, 192201, 24005, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アサヒ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (703, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 3.33, 0.0, 10046, 192201, 24006, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アサヒ", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (801, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0.0, 0.0, 10046, 192301, 24007, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "部員３", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (802, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 2.68, 0.0, 10046, 192301, 24008, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "部員３", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (803, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0.0, 0.0, 10046, 192301, 24009, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "部員３", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (501, "やった！", 0.0, 0.0, 10046, 192501, 24010, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (502, "勝ったよ！", 0.0, 0.0, 10046, 192501, 24011, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (503, "いい調子！", 0.0, 0.0, 10046, 192501, 24012, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (111, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 5.33, 0.0, 10046, 113501, 24013, 6, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (112, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 6.85, 0.0, 10046, 113501, 24014, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 3.0, 0.0, 10046, 113501, 24015, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (611, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 6.11, 0.0, 10046, 192401, 24016, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ダイチ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (612, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 6.75, 0.0, 10046, 192401, 24017, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ダイチ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (613, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0.0, 0.0, 10046, 192401, 24018, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ダイチ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (211, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 4.52, 0.0, 10046, 113401, 24019, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ハツネ", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (212, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 3.89, 0.0, 10046, 113401, 24020, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ハツネ", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (213, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 13.49, 0.0, 10046, 113401, 24021, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ハツネ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (311, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 3.17, 0.0, 10046, 106501, 24022, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "カヤ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (312, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 4.42, 0.0, 10046, 106501, 24023, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "カヤ", 0.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (313, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 2.89, 0.0, 10046, 106501, 24024, 6, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "カヤ", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (421, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 3.71, 0.0, 10046, 102301, 24025, 4, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アヤネ", 0.0, 3);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (721, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 5.1, 0.0, 10046, 192201, 24026, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "アサヒ", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (821, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 4.34, 0.0, 10046, 192301, 24027, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "部員３", 0.0, 3);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (521, "いい勝負だったよ\nまたやろうね", 0.0, 0.0, 10046, 192501, 24028, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "", 0.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (101, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 5.62, 0.0, 10046, 113501, 24029, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", -360.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (102, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 9.58, 0.0, 10046, 113501, 24030, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", -360.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (103, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 0.0, 0.0, 10046, 113501, 24031, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", -360.0, 2);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (104, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 9.13, 0.0, 10046, 113501, 24032, 2, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", -360.0, 1);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (105, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 8.27, 0.0, 10046, 113501, 24033, 1, "2020/07/31 12:00:00", "2030/12/17 14:59:59", 24, "ミサト", -360.0, 2);
